<template><view class="page"><view class="bar"><text @tap="back">‹</text><text>{{ isRoot ? '全站博客管理' : '我的博客' }}</text><text @tap="create">＋</text></view><scroll-view class="scroll" scroll-y refresher-enabled :refresher-triggered="refreshing" @refresherrefresh="load"><view class="content"><view class="intro"><text>{{ isRoot ? '可管理所有作者的博客，包括公开文章。' : '这里管理你创建的所有博客草稿和公开文章。' }}</text></view><view v-if="loading" class="state">正在读取文章…</view><view v-else-if="!posts.length" class="state" @tap="create">还没有文章，点此新建。</view><view v-else><view v-for="post in posts" :key="post.id" class="post" @tap="edit(post)"><image v-if="normalizeAssetUrl(post.cover_url)" class="cover" :src="normalizeAssetUrl(post.cover_url)" mode="aspectFill"/><view v-else class="cover placeholder">文</view><view class="copy"><text class="status" :class="post.is_public&&post.is_published?'public':'draft'">{{ label(post) }}</text><text class="title">{{ post.title }}</text><text class="meta">{{ author(post) }} · {{ date(post.updated_at) }}</text></view><text class="arrow">›</text></view></view></view></scroll-view></view></template>
<script>import{getCurrentUser,getMyBlogPosts,normalizeAssetUrl}from'../../services/api';export default{data(){return{posts:[],loading:true,refreshing:false,isRoot:false}},onLoad(){this.load()},onShow(){if(!this.loading)this.load()},methods:{normalizeAssetUrl,async load(){try{const[user,posts]=await Promise.all([getCurrentUser(),getMyBlogPosts()]);this.isRoot=Boolean(user&&user.is_root);this.posts=Array.isArray(posts)?posts:[]}catch(e){this.posts=[];uni.showToast({title:'请先登录并确认博客权限',icon:'none'})}finally{this.loading=false;this.refreshing=false}},label(p){return p.is_public&&p.is_published?'公开发布':p.is_published?'空间可见':'草稿'},author(p){return p.author?(p.author.display_name||p.author.username||'作者'):'作者'},date(v){if(!v)return'刚刚';const d=new Date(v);return d.getFullYear()+'.'+String(d.getMonth()+1).padStart(2,'0')+'.'+String(d.getDate()).padStart(2,'0')},create(){uni.navigateTo({url:'/pages/blog-editor/index'})},edit(p){uni.navigateTo({url:'/pages/blog-editor/index?id='+p.id})},back(){uni.navigateBack({delta:1})}}}</script>
<style scoped>.page{height:100vh;background:#f1eee5}.bar{height:calc(var(--status-bar-height) + 104rpx);padding:var(--status-bar-height) 28rpx 0;box-sizing:border-box;display:flex;align-items:center;justify-content:space-between;background:#fffdf8;color:#17211d;font-family:Georgia,'Songti SC',serif;font-size:27rpx;font-weight:700}.bar text:first-child,.bar text:last-child{width:60rpx;color:#1d6347;font-size:54rpx;line-height:52rpx}.bar text:last-child{text-align:right}.scroll{height:calc(100vh - var(--status-bar-height) - 104rpx)}.content{padding:28rpx}.intro{margin-bottom:20rpx;padding:23rpx;border-radius:24rpx;color:#5e482c;background:#f4d8a4;font-size:21rpx;line-height:32rpx}.state{padding:120rpx 25rpx;border-radius:30rpx;color:rgba(23,33,29,.48);background:#fffdf8;font-size:22rpx;text-align:center}.post{min-height:145rpx;padding:16rpx;display:flex;align-items:center;gap:17rpx;border-radius:26rpx;background:#fffdf8}.post+.post{margin-top:15rpx}.cover{width:112rpx;height:112rpx;border-radius:18rpx;background:#e4ecdf}.placeholder{display:flex;align-items:center;justify-content:center;color:#f7b84b;background:#163a2b;font-size:34rpx}.copy{min-width:0;flex:1}.status,.title,.meta{display:block;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.status{font-size:16rpx;font-weight:800;letter-spacing:2rpx}.public{color:#1d6347}.draft{color:#9b611f}.title{margin-top:8rpx;color:#17211d;font-family:Georgia,'Songti SC',serif;font-size:27rpx;font-weight:700}.meta{margin-top:9rpx;color:rgba(23,33,29,.4);font-size:18rpx}.arrow{color:rgba(23,33,29,.3);font-size:40rpx}</style>
